pub const Bin = extern struct {
    tag: Tag = Tag.none,
    _padding_tag: [3]u8 = @as([3]u8, @splat(@as(u8, 0))),
    value: Value = Value{ .map = ExternalStringList{  } },

pub fn count(self: Bin, buf: []const u8, extern_strings: []const ExternalString, comptime StringBuilder: type, builder: StringBuilder) u32 {
            switch (self.tag) {
.file => {
_ = builder.count(self.value.file.slice(buf));
},
.named_file => {
_ = builder.count(self.value.named_file[0].slice(buf));
            _ = builder.count(self.value.named_file[1].slice(buf));
},
.dir => {
_ = builder.count(self.value.dir.slice(buf));
},
.map => {
const list = self.value.map.get(extern_strings);
            for (cp_mut_slice(&list)) |*extern_string| {
                _ = &extern_string;
                _ = builder.count((extern_string.*).slice(buf));
            }
            return @as(u32, @truncate(list.len));
},
else => {

},
}
            return 0;
    }

pub fn eql(l: *const Bin, r: *const Bin, l_buf: []const u8, l_extern_strings: []const ExternalString, r_buf: []const u8, r_extern_strings: []const ExternalString) bool {
            if ((l.tag != r.tag)) {
                return false;
            }
            return (switch (l.tag) {
.none => true,
.file => l.value.file.eql(r.value.file, l_buf, r_buf),
.dir => l.value.dir.eql(r.value.dir, l_buf, r_buf),
.named_file => (l.value.named_file[0].eql(r.value.named_file[0], l_buf, r_buf) and l.value.named_file[1].eql(r.value.named_file[1], l_buf, r_buf)),
.map => {
{
                const l_list = l.value.map.get(l_extern_strings);
                const r_list = r.value.map.get(r_extern_strings);
                if ((l_list.len != r_list.len)) {
                    return false;
                }
                var i: usize = 0;
                _ = &i;
                outer: while ((i < l_list.len)) : (i = (i + 2)) {
                    var j: usize = 0;
                    _ = &j;
                    while ((j < r_list.len)) : (j = (j + 2)) {
                        if ((l_list[@as(usize, @intCast(i))].hash == r_list[@as(usize, @intCast(j))].hash)) {
                            if ((l_list[@as(usize, @intCast((i + 1)))].hash != r_list[@as(usize, @intCast((j + 1)))].hash)) {
                                return false;
                            }
                            continue :outer;
                        }
                    }
                    return false;
                }
                return true;
            }
},
});
    }

pub fn clone(self: Bin, buf: []const u8, prev_external_strings: []const ExternalString, all_extern_strings: []ExternalString, extern_strings_slice: []ExternalString, comptime StringBuilder: type, builder: StringBuilder) Bin {
            switch (self.tag) {
.none => {
return Bin{ .tag = .none, .value = Value.init(.{ .none = {} }) };
},
.file => {
return Bin{ .tag = .file, .value = Value.init(.{ .file = builder.append(String, self.value.file.slice(buf)) }) };
},
.named_file => {
return Bin{ .tag = .named_file, .value = Value.init(.{ .named_file = .{ builder.append(String, self.value.named_file[0].slice(buf)), builder.append(String, self.value.named_file[1].slice(buf)) } }) };
},
.dir => {
return Bin{ .tag = .dir, .value = Value.init(.{ .dir = builder.append(String, self.value.dir.slice(buf)) }) };
},
.map => {
const prev_list = self.value.map.get(prev_external_strings);
            var i: usize = 0;
            _ = &i;
            while ((i < prev_list.len)) : (i = (i + 1)) {
                extern_strings_slice[cp_cast_int(usize, i)] = builder.append(ExternalString, prev_list[@as(usize, @intCast(i))].slice(buf));
            }
            return Bin{ .tag = .map, .value = Value.init(.{ .map = ExternalStringList.init(all_extern_strings, extern_strings_slice) }) };
},
}
            _ = unreachable;
    }

pub fn parseAppend(allocator: std.mem.Allocator, bin_expr: BunJSON.Expr, buf: *String.Buf, extern_strings: *std.ArrayListUnmanaged(ExternalString)) OOM!Bin {
            switch (bin_expr.data) {
.e_object => |obj| {
switch (obj.properties.len) {
0 => {

},
1 => {
var bin_name: []const u8 = "";
            _ = &bin_name;
            if (obj.properties.ptr[0].key.?.asString(allocator)) |bn| {
                _ = &bn;
                bin_name = bn;
            } else {
                return .{};
            }
            var value: []const u8 = "";
            _ = &value;
            if ((if (@typeInfo(@TypeOf(obj.properties.ptr[0])) == .@"enum") @intFromEnum(obj.properties.ptr[0]) else obj.properties.ptr[0].value).?.asString(allocator)) |val| {
                _ = &val;
                value = val;
            } else {
                return .{};
            }
            return .{ .tag = .named_file, .value = .{ .named_file = .{ try buf.append(bin_name), try buf.append(value) } } };
},
else => {
const current_len = extern_strings.items.len;
            const num_props: usize = (obj.properties.len * 2);
            _ = try extern_strings.ensureTotalCapacityPrecise(allocator, (current_len + num_props));
            var new_items = extern_strings.items.ptr[current_len..(current_len + num_props)];
            _ = &new_items;
            extern_strings.items.len = (extern_strings.items.len + num_props);
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(obj.properties.slice())) |bin_prop| {
                _ = &bin_prop;
                const key = bin_prop.key.?;
                const value = (if (@typeInfo(@TypeOf(bin_prop)) == .@"enum") @intFromEnum(bin_prop) else bin_prop.value).?;
                var key_str: []const u8 = "";
                _ = &key_str;
                if (key.asString(allocator)) |ks| {
                    _ = &ks;
                    key_str = ks;
                } else {
                    return .{};
                }
                var value_str: []const u8 = "";
                _ = &value_str;
                if (value.asString(allocator)) |vs| {
                    _ = &vs;
                    value_str = vs;
                } else {
                    return .{};
                }
                new_items[cp_cast_int(usize, i)] = try buf.appendExternal(key_str);
                i = (i + 1);
                new_items[cp_cast_int(usize, i)] = try buf.appendExternal(value_str);
                i = (i + 1);
            }
            if (comptime Environment.allow_assert) {
                _ = bun.assert((i == new_items.len));
            }
            return .{ .tag = .map, .value = .{ .map = ExternalStringList.init(extern_strings.items, new_items) } };
},
}
},
.e_string => |str| {
if ((str.data.len > 0)) {
                return .{ .tag = .file, .value = .{ .file = try buf.append(str.data) } };
            }
},
else => {

},
}
            return .{};
    }

pub fn parseAppendFromDirectories(allocator: std.mem.Allocator, bin_expr: BunJSON.Expr, buf: *String.Buf) OOM!Bin {
            if (bin_expr.asString(allocator)) |bin_str| {
                _ = &bin_str;
                return .{ .tag = .dir, .value = .{ .dir = try buf.append(bin_str) } };
            }
            return .{};
    }

pub fn toJson(self: Bin, comptime style: FormatStyle, indent: if ((style == FormatStyle.multi_line)) *u32 else void, buf: []const u8, extern_strings: []const ExternalString, writer: *std.Io.Writer, writeIndent: WriteIndentFn) std.Io.Writer.Error!void {
            _ = bun.debugAssert((self.tag != .none));
            if (comptime (style == .single_line)) {
                switch (self.tag) {
.none => {

},
.file => {
_ = try writer.print("{f}", .{ self.value.file.fmtJson(buf, .{}) });
},
.named_file => {
_ = try writer.writeByte(123);
                _ = try writer.print(" {f}: {f} ", .{ self.value.named_file[0].fmtJson(buf, .{}), self.value.named_file[1].fmtJson(buf, .{}) });
                _ = try writer.writeByte(125);
},
.dir => {
_ = try writer.print("{f}", .{ self.value.dir.fmtJson(buf, .{}) });
},
.map => {
_ = try writer.writeByte(123);
                const list = self.value.map.get(extern_strings);
                var first = true;
                _ = &first;
                var i: usize = 0;
                _ = &i;
                while ((i < list.len)) : (i = (i + 2)) {
                    if ((!first)) {
                        _ = try writer.writeByte(44);
                    }
                    first = false;
                    _ = try writer.print(" {f}: {f}", .{ (if (@typeInfo(@TypeOf(list[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(list[@as(usize, @intCast(i))]) else list[@as(usize, @intCast(i))].value).fmtJson(buf, .{}), (if (@typeInfo(@TypeOf(list[@as(usize, @intCast((i + 1)))])) == .@"enum") @intFromEnum(list[@as(usize, @intCast((i + 1)))]) else list[@as(usize, @intCast((i + 1)))].value).fmtJson(buf, .{}) });
                }
                _ = try writer.writeAll(" }");
},
}
                return;
            }
            switch (self.tag) {
.none => {

},
.file => {
_ = try writer.print("{f}", .{ self.value.file.fmtJson(buf, .{}) });
},
.named_file => {
_ = try writer.writeAll("{\n");
            indent.* = (indent.* + 1);
            _ = try writeIndent(writer, indent);
            _ = try writer.print("{f}: {f},\n", .{ self.value.named_file[0].fmtJson(buf, .{}), self.value.named_file[1].fmtJson(buf, .{}) });
            indent.* = (indent.* - 1);
            _ = try writeIndent(writer, indent);
            _ = try writer.writeByte(125);
},
.dir => {
_ = try writer.print("{f}", .{ self.value.dir.fmtJson(buf, .{}) });
},
.map => {
_ = try writer.writeByte(123);
            indent.* = (indent.* + 1);
            const list = self.value.map.get(extern_strings);
            var has_any = false;
            _ = &has_any;
            var i: usize = 0;
            _ = &i;
            while ((i < list.len)) : (i = (i + 2)) {
                if ((!has_any)) {
                    has_any = true;
                    _ = try writer.writeByte(10);
                }
                _ = try writeIndent(writer, indent);
                _ = try writer.print("{f}: {f},\n", .{ (if (@typeInfo(@TypeOf(list[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(list[@as(usize, @intCast(i))]) else list[@as(usize, @intCast(i))].value).fmtJson(buf, .{}), (if (@typeInfo(@TypeOf(list[@as(usize, @intCast((i + 1)))])) == .@"enum") @intFromEnum(list[@as(usize, @intCast((i + 1)))]) else list[@as(usize, @intCast((i + 1)))].value).fmtJson(buf, .{}) });
            }
            if ((!has_any)) {
                _ = try writer.writeByte(125);
                indent.* = (indent.* - 1);
                return;
            }
            indent.* = (indent.* - 1);
            _ = try writeIndent(writer, indent);
            _ = try writer.writeByte(125);
},
}
    }

pub fn init() Bin {
            return bun.serializable(Bin{ .tag = .none, .value = Value.init(.{ .none = {} }) });
    }

pub fn normalizedBinName(name: []const u8) []const u8 {
            const result = (if (std.mem.lastIndexOfAny(u8, name, "/\\:")) |i| name[(i + 1)..] else name);
            if ((std.mem.eql(u8, result, ".") or std.mem.eql(u8, result, ".."))) {
                return "";
            }
            return result;
    }
