            } else {
                self.done = true;
                _ = self.dir_iterator.?.dir.close();
                self.dir_iterator = null;
                return null;
            }
    }

pub fn next(self: *BinNamesIterator) !?[]const u8 {
            switch (self.bin.tag) {
.file => {
if ((self.i > 0)) {
                return null;
            }
            self.i = (self.i + 1);
            self.done = true;
            const base = std.fs.path.basename(@TypeOf(self.package_name).slice((&self.package_name), self.string_buffer));
            if ((strings.hasPrefixComptime(base, "./") or strings.hasPrefixComptime(base, ".\\"))) {
                return strings.copy((&self.buf), base[2..]);
            }
            return strings.copy((&self.buf), base);
